<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {Image,Check,Download} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {loadOriginalPack,copyOriginalAsset,type OriginalAsset,type OriginalPack} from './original-pack'
const emit=defineEmits<{close:[];saved:[id:string]}>(),store=useLocal(),pack=ref<OriginalPack|null>(null),filter=ref('all'),images=ref(!(navigator as Navigator&{connection?:{saveData?:boolean}}).connection?.saveData),error=ref(''),busy=ref<string|null>(null),selected=ref<Record<string,string>>({}),saved=ref(new Map<string,string>()),broken=ref(new Set<string>())
const labels:Record<string,string>={cover:'封面','stage-background':'场景','stage-portrait':'角色',neutral:'中性',joy:'喜悦',worry:'忧虑','standing-960':'立绘','standing-1536':'高清立绘','avatar-256':'小头像','avatar-512':'头像','half-480':'半身','half-768':'高清半身'}
const visible=computed(()=>pack.value?.assets.filter(a=>filter.value==='all'||a.purpose===filter.value)||[])
const control=new AbortController();let disposed=false
function preview(a:OriginalAsset){return a.variants.find(v=>v.role==='avatar-256')||a.variants.reduce((old,v)=>v.bytes<old.bytes?v:old,a.variants[0]!)}
function defaultRole(a:OriginalAsset){return a.variants.find(v=>v.role==='standing-960')?.role||preview(a).role}
function key(a:OriginalAsset){return a.id+'|'+(selected.value[a.id]||defaultRole(a))}
function failed(id:string){broken.value=new Set([...broken.value,id])}
async function load(){error.value='';try{const value=await loadOriginalPack(control.signal);if(!disposed)pack.value=value}catch(e){if(!disposed)error.value=(e as Error).message}}
async function save(a:OriginalAsset){const vault=store.vault;if(!vault||busy.value)return;const role=selected.value[a.id]||defaultRole(a),saveKey=a.id+'|'+role;busy.value=a.id;error.value='';try{const row=await copyOriginalAsset(vault,a,role,control.signal);if(disposed||store.vault!==vault||!vault.unlocked)return;saved.value=new Map(saved.value).set(saveKey,row.id);window.dispatchEvent(new CustomEvent('reader-media-changed',{detail:{vaultId:vault.id}}));emit('saved',row.id)}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=null}}
onMounted(load)
onUnmounted(()=>{disposed=true;control.abort();pack.value=null;saved.value.clear()})
</script>
<template><Sheet title="原创素材" @close="emit('close')"><div class="original-pack-toolbar"><select v-model="filter" aria-label="素材类型"><option value="all">全部</option><option value="stage-portrait">角色</option><option value="stage-background">场景</option><option value="cover">封面</option></select><label><input v-model="images" type="checkbox">显示预览</label></div><p v-if="error" class="final-error" role="alert">{{error}}<button v-if="!pack" @click="load">重试</button></p><p v-if="!pack&&!error" role="status">正在打开素材…</p><div class="original-pack-grid"><article v-for="a in visible" :key="a.id"><div class="original-pack-preview"><img v-if="images&&!broken.has(a.id)" :src="preview(a).url" :width="preview(a).width" :height="preview(a).height" :alt="a.name+(a.expression?' · '+labels[a.expression]:'')" loading="lazy" @error="failed(a.id)"><Image v-else :size="32" aria-hidden="true"/></div><h3>{{a.name}}</h3><small>{{labels[a.purpose]}}{{a.expression?' · '+labels[a.expression]:''}}</small><select :value="selected[a.id]||defaultRole(a)" :aria-label="a.name+' '+(labels[a.expression]||'')+'素材尺寸'" @change="selected[a.id]=($event.target as HTMLSelectElement).value"><option v-for="v in a.variants" :key="v.role" :value="v.role">{{labels[v.role]||v.width+' × '+v.height}} · {{Math.ceil(v.bytes/1024)}} KB</option></select><button :disabled="!!busy" @click="save(a)"><Check v-if="saved.has(key(a))" :size="16"/><Download v-else :size="16"/>{{busy===a.id?'正在保存…':saved.has(key(a))?'已加入':'加入素材库'}}</button></article></div></Sheet></template>
<style scoped>.original-pack-toolbar{display:flex;gap:16px;align-items:center;margin-bottom:20px}.original-pack-toolbar select{max-width:150px}.original-pack-toolbar label{display:flex;align-items:center;gap:7px;font-size:13px}.original-pack-toolbar input{width:auto}.original-pack-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.original-pack-grid article{min-width:0;display:grid;gap:10px;align-content:start}.original-pack-preview{height:160px;border:1px solid var(--edge);border-radius:14px;background:var(--wash);display:grid;place-items:center;overflow:hidden;color:var(--muted)}.original-pack-preview img{width:100%;height:100%;object-fit:contain}.original-pack-grid h3{margin:0;font:20px var(--font-serif);overflow-wrap:anywhere}.original-pack-grid small{color:var(--muted)}.original-pack-grid select{font-size:12px;width:100%;min-width:0;min-height:44px}.original-pack-grid button{min-height:44px;justify-content:center;font-size:13px}@media(max-width:600px){.original-pack-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.original-pack-preview{height:135px}}</style>
